  baby_food: { n: 'Banana Baby Food', c: '#f0e0a0', f: 'Banana purée with a pinch of ascorbic acid to stop it browning, hot-filled into small glass jars' },
  banana_fibre: { n: 'Banana Fibre', c: '#d8d0a8', f: 'Long fibre scraped from pseudostem sheaths, glossy and strong like a coarse silk' },
  banana_paper: { n: 'Banana Paper', c: '#e0d8c0', f: 'Handmade-style paper of banana fibre, used for stationery and gift wrap' },
  abaca_stalk: { n: 'Abaca Stalks', c: '#5a7a40', f: 'Pseudostems of Musa textilis, a banana grown in the Philippines for its fibre rather than its fruit, which is full of seeds' },
  abaca_fibre: { n: 'Abaca Fibre', c: '#e8e0c0', f: 'Manila hemp: the strongest natural fibre in common use, and one that does not rot in salt water' },
  manila_rope: { n: 'Manila Rope', c: '#c8b080', f: 'Three-strand rope laid from abaca yarn. It barely stretches and stays strong when wet, so it rigged sailing ships for a century' },
  layer_feed: { n: 'Layer Feed', c: '#c8a050', f: 'Mash of maize and soybean meal with about 4% limestone grit, so each hen can lay down two grams of calcium carbonate shell a day' },
  egg: { n: 'Eggs', c: '#e8d8c0', f: 'Hens\' eggs straight from the belt: about 10% shell, 60% white and 30% yolk by weight' },
  egg_box: { n: 'Boxed Eggs', c: '#d8c8a8', f: 'Washed, candled and graded eggs in moulded pulp boxes of a dozen, stamped with a code for the farm they came from' },
  eggshell: { n: 'Eggshell', c: '#f0e8dc', f: 'Wet broken shells from the breaking line, about 95% calcium carbonate lined with a thin protein membrane' },
  eggshell_membrane: { n: 'Eggshell Membrane', c: '#e8e0c8', f: 'The tough film under the shell, a mesh of collagen, keratin and glycosaminoglycans. Sold dried and milled as a joint supplement' },
  shell_calcium: { n: 'Eggshell Calcium', c: '#f4f0e8', f: 'Washed, heated and finely milled eggshell, about 38% calcium as carbonate. Goes into feed, fertiliser and calcium tablets' },
  egg_powder: { n: 'Whole Egg Powder', c: '#f0d870', f: 'Pasteurised liquid egg spray-dried to about 4% moisture. Bakeries and ration packs use it because it keeps for a year' },
  albumen_powder: { n: 'Egg White Powder', c: '#f8f4e8', f: 'Desugared, spray-dried and hot-room-aged albumen. It whips into meringue and binds surimi and ham' },
  lysozyme: { n: 'Lysozyme', c: '#f0f0f8', f: 'An enzyme that splits the cell walls of bacteria, about 3.5% of egg white protein. Alexander Fleming found it in his own nasal mucus in 1922' },
