  broiler: { n: 'Broilers', c: '#f0e8e0', f: 'Meat chickens reared to about 2.5 kg in six weeks on a feed of maize and soybean meal' },
  chicken: { n: 'Whole Chickens', c: '#f0d8b8', f: 'Plucked, eviscerated, air-chilled and bagged birds' },
  feathers: { n: 'Feathers', c: '#f8f8f0', f: 'Wet feathers from the pluckers, about 90% keratin held together by disulfide bridges, so animals cannot digest them raw' },
  feather_meal: { n: 'Hydrolysed Feather Meal', c: '#b89868', f: 'Feathers cooked under steam pressure until the keratin breaks down, then dried. About 80% protein, used in pet food and fish feed' },
  poultry_litter: { n: 'Poultry Litter', c: '#8a7a50', f: 'Wood shavings mixed with droppings, rich in nitrogen and phosphate' },
  litter_pellet: { n: 'Poultry Manure Pellets', c: '#6a5a3a', f: 'Composted litter dried and pelleted into a slow organic fertiliser, about 4-3-3 NPK' },
  mn_ore: { n: 'Manganese Ore', c: '#3a3230', f: 'Pyrolusite MnO₂ and psilomelane, sooty black and stains the fingers. Sedimentary beds laid down in shallow seas 2.2 billion years ago, about 40% Mn' },
  mn_conc: { n: 'Manganese Concentrate', c: '#2a2422', f: 'Washed and jigged manganese oxide lumps and fines, about 48% Mn with the clay and quartz washed away' },
  femn: { n: 'Ferromanganese', c: '#9a9088', f: 'High-carbon ferromanganese: 76% Mn, 7% C, the rest iron. Nine tenths of all manganese ends up in steel, about 7 kg in every tonne' },
  simn: { n: 'Silicomanganese', c: '#8a8890', f: 'About 66% Mn, 17% Si and 2% C. It deoxidises steel with silicon and manganese at once, and the oxides it forms float off as a runny slag' },
  mno_calcine: { n: 'Manganese Calcine', c: '#5a6a48', f: 'MnO, a dull green powder from roasting the ore with coal. The dioxide will not dissolve in dilute acid, the monoxide dissolves readily' },
  mn_metal: { n: 'Electrolytic Manganese', c: '#b8b4b0', f: 'Brittle silvery flakes of 99.7% Mn stripped from stainless cathodes. Too brittle to use alone, it goes into aluminium can alloys and low-nickel stainless' },
  emd: { n: 'Electrolytic Manganese Dioxide', c: '#2e2a2a', f: 'γ-MnO₂ grown on titanium anodes in hot acid, chipped off, ground and neutralised. Purer and more active than any natural ore' },
  alk_cell: { n: 'Alkaline Cell', c: '#b08a3a', f: 'A 1.5 V cylinder cell: manganese dioxide and graphite pressed against the steel can, zinc powder gel in the core, potassium hydroxide in between' },
