  kmno4: { n: 'Potassium Permanganate', c: '#6a1a5a', f: 'KMnO₄, nearly black needles with a green sheen that dissolve to an intense purple. Waterworks dose it to oxidise iron, manganese and taste-causing organics' },
  mn3o4: { n: 'Manganese Oxide Powder', c: '#6a4a3a', f: 'Hausmannite Mn₃O₄, a fine brown powder of uniform grains. The manganese source for soft ferrites' },
  ferrite_core: { n: 'Ferrite Core', c: '#3a3a3a', f: 'Sintered manganese-zinc ferrite, a black ceramic that is magnetic but does not conduct, so eddy currents cannot heat it. The core of every switched-mode power supply' },
  mn_steel: { n: 'Hadfield Steel', c: '#8a8678', f: '12-14% Mn, 1.2% C, water-quenched from 1050°C so it stays austenitic. Hammering hardens the surface while the core stays tough' },
  rail_frog: { n: 'Crossing Frog', c: '#7a7670', f: 'The V-shaped casting where two rails cross at a set of points. Every wheel slams across the gap, and the Hadfield steel work-hardens under the blows' },
  jaw_plate: { n: 'Crusher Jaw Plate', c: '#6a665e', f: 'Ribbed Hadfield steel liner for a jaw crusher. Rock blows harden the face to over 500 Brinell; ordinary steel would be worn smooth in a week' },
  nmc_pre: { n: 'NMC Precursor', c: '#5a6a4a', f: 'Ni₀.₈Mn₀.₁Co₀.₁(OH)₂, spherical grains about 10 µm across, each grown layer on layer like an onion in a stirred tank' },
  nmc: { n: 'NMC Cathode', c: '#2a2a32', f: 'LiNi₀.₈Mn₀.₁Co₀.₁O₂, NMC 811. Nickel carries the charge, cobalt keeps the layers ordered and manganese holds the structure together' },
  nmc_cell: { n: 'NMC Pouch Cell', c: '#4a5a6a', f: 'Stacked cathode and anode sheets sealed in aluminium-laminate film. About 270 Wh/kg, the cell in most long-range electric cars' },
  sb_ore: { n: 'Stibnite Ore', c: '#4a4c54', f: 'Quartz veins threaded with long lead-grey blades of stibnite, Sb₂S₃. The crystals are soft enough to bend and melt in a candle flame' },
  sb_conc: { n: 'Stibnite Concentrate', c: '#5a5c66', f: 'Floated stibnite, about 55% antimony, the quartz left behind in the tailings' },
  sb2o3: { n: 'Antimony Trioxide', c: '#f4f4f0', f: 'Sb₂O₃, a fine white smoke caught in bag filters. On its own it hardly slows a fire; mixed with brominated or chlorinated additives it makes antimony halides that smother the flame' },
  sb_metal: { n: 'Antimony Regulus', c: '#b8bcc4', f: 'Antimony cast in cakes with a star of fern-like crystals on the top. Hard, brittle and one of the few metals that expands as it freezes' },
  babbitt: { n: 'Babbitt Metal', c: '#c8ccc8', f: 'Tin with 7% antimony and 4% copper. Hard cubes of SbSn and needles of Cu₆Sn₅ carry the shaft while the soft tin around them lets grit bed in harmlessly' },
  plain_bearing: { n: 'Babbitt-Lined Bearing', c: '#a8aca8', f: 'A steel shell spun with a thin lining of white metal. The shaft rides on a wedge of oil and never touches the metal while it turns' },
  pewter: { n: 'Pewter', c: '#a8acb0', f: 'Modern lead-free pewter: 92% tin, 6% antimony, 2% copper. It melts at about 250°C and casts sharp detail in rubber or bronze moulds' },
  bronze: { n: 'Tin Bronze', c: '#b08a50', f: 'Copper with 10% tin, the alloy that named an age. Harder than either metal alone and it casts beautifully' },
  bell: { n: 'Cast Bronze Bell', c: '#9a7a40', f: 'Bell metal, 78% copper and 22% tin: too brittle to hammer, but it rings for a minute after a single strike' },
  cu3p: { n: 'Phosphor Copper', c: '#6a5a50', f: 'Cu₃P master alloy, about 15% phosphorus, cast in notched waffle plates. It melts low and dissolves fast, so it carries phosphorus into a copper melt without burning' },
  phos_bronze: { n: 'Phosphor Bronze', c: '#c09858', f: 'CuSn5 with 0.2% phosphorus. The phosphorus mops up oxygen in the melt, and the tin gives a strip that springs back millions of times' },
