  cuni_tube: { n: 'Condenser Tubes', c: '#c0a090', f: 'Seamless 90/10 cupronickel tubes. A ship or desalination plant cools seawater through thousands of them for decades' },
  nickel_silver: { n: 'Nickel Silver', c: '#d8d4c8', f: 'Copper with 20% zinc and 18% nickel. It holds no silver at all but looks it, and takes plating well' },
  key_blank: { n: 'Key Blanks', c: '#d0ccc0', f: 'Nickel silver blanks with the warding already milled, waiting to be cut to a lock. Hard enough to last, soft enough to cut in a minute' },
  monel: { n: 'Monel', c: '#b0aca0', f: 'About 67% nickel and 30% copper, close to the ratio found in some Sudbury ore. It resists seawater, alkali and even hydrofluoric acid' },
  invar: { n: 'Invar', c: '#a0a4a8', f: 'Iron with 36% nickel. Its magnetism cancels its thermal expansion so neatly that a metre bar grows barely a micrometre per degree' },
  invar_sheet: { n: 'Invar Membrane Sheet', c: '#9aa0a8', f: 'Corrugated sheet 0.7 mm thick for the inner skin of LNG carrier tanks. At −163°C it shrinks so little that it needs no expansion joints' },
  kovar: { n: 'Kovar', c: '#9a9ca4', f: 'Fe-29Ni-17Co. It expands with temperature at exactly the rate of hard borosilicate glass, so the two can be fused together without cracking' },
  glass_seal: { n: 'Glass-to-Metal Seals', c: '#8a9aa8', f: 'Kovar pins fused through glass beads in a kovar header. They carry current into vacuum tubes, sensors and laser packages while keeping out every trace of air' },
  nitinol: { n: 'Nitinol', c: '#8a8c98', f: 'Nearly equiatomic nickel and titanium. Bent cold, it springs back on warming as the crystal snaps from martensite to austenite' },
