  beeswax_candle: { n: 'Beeswax Candles', c: '#f4d870', f: 'Golden poured candles that burn slowly, smell faintly of honey and drip less than paraffin' },
  propolis: { n: 'Propolis', c: '#6a4a2a', f: 'Bee glue: resin the bees collect from tree buds and use to seal cracks in the hive. Rich in flavonoids and caffeic acid esters' },
  propolis_tincture: { n: 'Propolis Tincture', c: '#8a5a2a', f: 'Propolis dissolved in 70% ethanol and filtered, sold in dropper bottles' },
  lip_balm: { n: 'Lip Balm', c: '#e8a8a0', f: 'Sticks of beeswax, lanolin and vegetable oil. The wax gives structure and the lanolin seals moisture into the skin' },
  mead_bottle: { n: 'Bottled Mead', c: '#d8b040', f: 'Honey wine at about 12% alcohol, one of the oldest fermented drinks' },
  cryolite: { n: 'Cryolite', c: '#e8eef0', f: 'Sodium hexafluoroaluminate Na₃AlF₆. Molten, it dissolves alumina like water dissolves salt' },
